changeSet.sql:
INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver órdenes de compra', 'purchaseOrder.read', (SELECT id FROM sub_modules WHERE code = 'PURCHASES'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'purchaseOrder.read');

